// 1. Get the article text (Using .first() to avoid item linking errors)
const content = $('Code-solid-AI-Output').first().json.content;

// 2. Get the URL for the second image
const imageUrl = $('Media:uploadOther media-Cover').first().json.url;

// 3. Create the HTML image tag
const imageHtml = `<br><img src="${imageUrl}" alt="Image" style="width: 100%; border-radius: 8px;" /><br>`;

// 4. Inject the image after the SECOND paragraph
let newContent;
let count = 0; // Initialize a counter to track paragraphs

if (content.includes('</p>')) {
  // HTML Mode: Find closing paragraph tags </p>
  // We use a "callback function" inside replace to count them
  newContent = content.replace(/<\/p>/g, (match) => {
    count++;
    if (count === 3) { 
      // If this is the 2nd paragraph, append the image after the tag
      return match + imageHtml;
    }
    // Otherwise, just return the tag as is
    return match;
  });
} else {
  // Plain Text Mode: Find double newlines \n\n
  newContent = content.replace(/\n\n/g, (match) => {
    count++;
    if (count === 2) {
      // If this is the 2nd break, insert: Newline + Image + Newline
      return match + imageHtml + match;
    }
    return match;
  });
}

// SAFETY FALLBACK: 
// If the article is short (has less than 2 paragraphs), 'count' will be less than 2.
// In that case, we append the image to the very end so it isn't lost.
if (count < 2) {
  newContent = content + imageHtml;
}

// 5. Output the result
return {
  json: {
    final_content: newContent
  }
};

// 1. Get the output from the AI Agent node
const aiOutput = $input.first().json.output || $input.first().json.text; 

// 2. Helper to clean Markdown wrappers
function cleanMarkdown(text) {
    const jsonMatch = text.match(/```json\s*([\s\S]*?)\s*```/) || text.match(/```\s*([\s\S]*?)\s*```/);
    return jsonMatch ? jsonMatch[1] : text;
}

let jsonString = cleanMarkdown(aiOutput);
let finalData = {};

try {
    // STRATEGY A: Try standard parsing first (Best Case)
    finalData = JSON.parse(jsonString);

} catch (e) {
    // STRATEGY B: Regex Extraction (Fallback)
    // This extracts each field individually, regardless of valid JSON structure.

    // Function to grab text specifically for a given key
    const getField = (key) => {
        // Regex Logic:
        // 1. Find "key":
        // 2. Allow for optional quote opening (")
        // 3. Capture everything ([^]*) until...
        // 4. ...we hit the next quote-key sequence (", "next) OR the end of the JSON (})
        // Note: This relies on the keys being unique strings in the text.

        // Simpler, specific regexes for your known schema:
        const regexMap = {
            "title": /"title"\s*:\s*"(.*?)"\s*,\s*"content"/s,
            "content": /"content"\s*:\s*"(.*?)"\s*,\s*"picture_cover_prompts"/s,
            "picture_cover_prompts": /"picture_cover_prompts"\s*:\s*"(.*?)"\s*,\s*"picture_content_prompts"/s
        };

        const match = jsonString.match(regexMap[key]);
        return match ? match[1] : null; // Returns null if field is missing
    };

    finalData = {
        title: getField("title"),
        content: getField("content"),
        picture_cover_prompts: getField("picture_cover_prompts"),
        picture_content_prompts: getField("picture_content_prompts"),
        _status: "parsed_with_regex_fallback"
    };
}

// 3. Return the object containing ALL fields
return finalData;
